import { createHash } from "node:crypto";
import { describe, expect, it } from "vitest";
import {
  STARTER_CONFIGURATION_DESCRIPTION,
  STARTER_CONFIGURATION_NAME,
  STARTER_CONFIGURATION_YAML,
} from "./starter-configuration.js";

/**
 * The starter's YAML, line by line, written differently from the constant so
 * that an edit to one isn't copied into the other.
 */
const SPEC_LINES = [
  "# OpenTelemetry Collector Configuration",
  "# Generated by Telflo",
  "",
  "receivers:",
  "  otlp:",
  "    protocols:",
  "      grpc:",
  "        endpoint: '0.0.0.0:4317'",
  "      http:",
  "        endpoint: '0.0.0.0:4318'",
  "processors:",
  "  batch:",
  "    timeout: '10s'",
  "    send_batch_size: 1024",
  "exporters:",
  "  otlp:",
  "    endpoint: 'otelcol:4317'",
  "    tls:",
  "      insecure: true",
  "extensions:",
  "  health_check:",
  "    endpoint: '0.0.0.0:13133'",
  "  pprof:",
  "    endpoint: '0.0.0.0:1777'",
  "  zpages:",
  "    endpoint: '0.0.0.0:55679'",
  "service:",
  "  extensions: [health_check, pprof, zpages]",
  "  pipelines:",
  "    traces:",
  "      receivers: [otlp]",
  "      processors: [batch]",
  "      exporters: [otlp]",
  "    metrics:",
  "      receivers: [otlp]",
  "      processors: [batch]",
  "      exporters: [otlp]",
  "    logs:",
  "      receivers: [otlp]",
  "      processors: [batch]",
  "      exporters: [otlp]",
];

/** The SHA-256 of the starter YAML, as UTF-8. */
const STARTER_YAML_SHA256 = "de34f5a5cd771255ec4434decd2c6f8d322560c7235091c56cd7b32ef172d8dd";

describe("the starter configuration", () => {
  it("has its fixed name and description", () => {
    expect(STARTER_CONFIGURATION_NAME).toBe("Initial Configuration");
    expect(STARTER_CONFIGURATION_DESCRIPTION).toBe("Default OTel Collector pipeline created on signup");
  });

  it("holds the expected YAML exactly, ending in one newline", () => {
    expect(STARTER_CONFIGURATION_YAML).toBe(`${SPEC_LINES.join("\n")}\n`);
    expect(STARTER_CONFIGURATION_YAML.endsWith("]\n")).toBe(true);
    expect(STARTER_CONFIGURATION_YAML).not.toContain("\r");
  });

  it("has the pinned SHA-256, so an accidental edit is loud", () => {
    expect(createHash("sha256").update(STARTER_CONFIGURATION_YAML, "utf8").digest("hex")).toBe(STARTER_YAML_SHA256);
  });
});
